package com.mo.economy_system.target.neoforge1211.protocol;
import com.mo.economy_system.common.network.*;import com.mo.economy_system.common.transfer.CheckedFileTransferRoutingService;import net.minecraft.server.level.ServerPlayer;import net.neoforged.neoforge.network.handling.IPayloadContext;
final class NeoForge1211CheckedFileTransferHandlers{private NeoForge1211CheckedFileTransferHandlers(){}
 static void controlRequest(CheckedFileTransferControlRequestMessage m,IPayloadContext c){c.enqueueWork(()->{if(c.player() instanceof ServerPlayer p){var server=p.getServer();CheckedFileTransferRoutingService.control(m,p.getUUID(),server.overworld().getGameTime(),NeoForge1211ClientFileCheckRuntime.transfers(server).transfers(),id->server.getPlayerList().getPlayer(id),(player,msg)->com.mo.economy_system.network.EconomySystem_NetworkManager.sendToClient((ServerPlayer)player,(com.mo.economy_system.platform.network.EconomyNetworkMessage)msg));}});}
 static void chunkRequest(CheckedFileTransferChunkRequestMessage m,IPayloadContext c){c.enqueueWork(()->{if(c.player() instanceof ServerPlayer p){var server=p.getServer();CheckedFileTransferRoutingService.chunk(m,p.getUUID(),server.overworld().getGameTime(),NeoForge1211ClientFileCheckRuntime.transfers(server).transfers(),id->server.getPlayerList().getPlayer(id),(player,msg)->com.mo.economy_system.network.EconomySystem_NetworkManager.sendToClient((ServerPlayer)player,(com.mo.economy_system.platform.network.EconomyNetworkMessage)msg));}});}
 static void request(CheckedFileTransferRequestMessage m,IPayloadContext c){c.enqueueWork(()->com.mo.economy_system.target.neoforge1211.client.NeoForge1211CheckedFileTransferClient.handle(m));}static void controlResponse(CheckedFileTransferControlResponseMessage m,IPayloadContext c){c.enqueueWork(()->com.mo.economy_system.target.neoforge1211.client.NeoForge1211CheckedFileTransferClient.control(m));}static void chunkResponse(CheckedFileTransferChunkResponseMessage m,IPayloadContext c){c.enqueueWork(()->com.mo.economy_system.target.neoforge1211.client.NeoForge1211CheckedFileTransferClient.chunk(m));}
}
